import { supabaseRequest } from "../_lib/supabase.js";
const OWNER_EMAIL="m.colurci@gmail.com";
export default async function handler(req,res){if(req.method!=="POST"){res.setHeader("Allow","POST");return res.status(405).json({ok:false,error:"Method not allowed"});}try{const owners=await supabaseRequest("/rest/v1/profiles?role=in.(owner,admin)&select=email&limit=1");if(owners?.length)return res.status(403).json({ok:false,error:"Owner already set"});const rows=await supabaseRequest("/rest/v1/profiles?on_conflict=email",{method:"POST",headers:{Prefer:"resolution=merge-duplicates,return=representation"},body:[{email:OWNER_EMAIL,username:"Mike",name:"Mike",role:"owner"}]});return res.status(200).json({ok:true,owner:{email:rows?.[0]?.email||OWNER_EMAIL,role:"owner"}});}catch(err){return res.status(500).json({ok:false,error:err?.message||String(err)});}}
